const PARTS=[1,2,9];
function eligible(q){return PARTS.includes(q?.part)}
function gradable(q){return eligible(q)&&q.status==='verified'&&q.answerVerified&&q.choices.some(c=>c.id===q.correctAnswer)}
function blocks(bank,part){const qs=bank.filter(q=>q.part===part&&gradable(q));return Array.from({length:Math.ceil(qs.length/10)},(_,i)=>({id:`p${part}-b${i+1}`,part,index:i,ids:qs.slice(i*10,i*10+10).map(q=>q.id)}))}
function readyBlocks(bank,part,state){return blocks(bank,part).filter(b=>b.ids.every(id=>state.understood[id])&&!state.tests.some(t=>t.blockId===b.id))}
function score(ids,answers,bank){const byId=new Map(bank.map(q=>[q.id,q]));if(ids.some(id=>!gradable(byId.get(id))))throw Error('This test contains an unresolved question.');return {correct:ids.filter(id=>answers[id]===byId.get(id).correctAnswer).length,total:ids.length}}
function fresh(){return {version:1,understood:{},bookmarks:{},revision:{},position:{},attempts:[],tests:[],history:[]}}
function validateProgress(value,bank){if(!value||value.version!==1)throw Error('Unsupported progress file.');const ids=new Set(bank.map(q=>q.id));const out=fresh();for(const key of ['understood','bookmarks','revision']){if(!value[key]||typeof value[key]!=='object'||Array.isArray(value[key]))throw Error('Invalid '+key);for(const [id,v] of Object.entries(value[key]))if(ids.has(id)&&v===true)out[key][id]=true;}
if(!Array.isArray(value.attempts)||!Array.isArray(value.tests)||value.attempts.length>100000||value.tests.length>10000)throw Error('Invalid attempt history.');
out.attempts=value.attempts.filter(a=>ids.has(a.id)&&['A','B','C','D','E'].includes(a.selected)&&typeof a.correct==='boolean'&&Number.isFinite(a.time)).map(a=>({id:a.id,selected:a.selected,correct:a.correct,time:a.time,mode:String(a.mode||'practice'),round:Number(a.round)||1}));
const validBlocks=new Map(PARTS.flatMap(p=>blocks(bank,p)).map(b=>[b.id,b]));
out.tests=value.tests.filter(t=>validBlocks.has(t.blockId)&&Number.isFinite(t.time)&&t.answers&&typeof t.answers==='object').map(t=>{const b=validBlocks.get(t.blockId);const answers=Object.fromEntries(b.ids.filter(id=>['A','B','C','D','E'].includes(t.answers[id])).map(id=>[id,t.answers[id]]));if(Object.keys(answers).length!==b.ids.length)throw Error('Incomplete test in backup.');return {blockId:b.id,time:t.time,answers,...score(b.ids,answers,bank)}});
for(const p of PARTS)if(ids.has(value.position?.[p]))out.position[p]=value.position[p];out.history=Array.isArray(value.history)?value.history.slice(-500).filter(h=>ids.has(h.id)&&Number.isFinite(h.time)):[];return out}
function stats(bank,s){const attempts=s.attempts;const latest=new Map(attempts.map(a=>[a.id,a]));return {total:bank.length,studied:bank.filter(q=>s.understood[q.id]).length,attempted:latest.size,correct:[...latest.values()].filter(a=>a.correct).length,wrong:attempts.filter(a=>!a.correct).length,accuracy:attempts.length?Math.round(100*attempts.filter(a=>a.correct).length/attempts.length):0,mistakes:[...new Set(attempts.filter(a=>!a.correct).map(a=>a.id))]}}
let db,chain=Promise.resolve(),memoryProgress;
async function openStore(){
  if(!('indexedDB' in window)){memoryProgress=fresh();return memoryProgress}
  try{
    db=await new Promise((resolve,reject)=>{const r=indexedDB.open('learnova-biology-129',1);r.onupgradeneeded=()=>r.result.createObjectStore('progress');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
    return await new Promise((resolve,reject)=>{const r=db.transaction('progress').objectStore('progress').get('student');r.onsuccess=()=>resolve(r.result||fresh());r.onerror=()=>reject(r.error)})
  }catch{memoryProgress=fresh();return memoryProgress}
}
function save(state){const snapshot=structuredClone(state);if(!db){memoryProgress=snapshot;return Promise.resolve()}chain=chain.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{const tx=db.transaction('progress','readwrite');tx.objectStore('progress').put(snapshot,'student');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)}));return chain}
async function importFile(file,bank){if(file.size>10000000)throw Error('Backup is too large.');return validateProgress(JSON.parse(await file.text()),bank)}
let bank=[],state,route='dashboard',viewIds=[],current=null,selected=null,feedback=null,round=1,test=null,result=null,filter={part:'all',source:'all',status:'all',query:''},page=0;
