function shell(body){$('#app').innerHTML='<div class="shell"><aside class="sidebar"><a href="#dashboard" class="brand"><i>⌁</i>learnova<small>.</small></a><div class="side-label">YOUR STUDY SPACE</div><nav class="nav" aria-label="Main navigation">'+Object.entries(titles).map(([r,t])=>'<a href="#'+r+'" class="'+(route===r?'active':'')+'"><span aria-hidden="true">'+icons[r]+'</span><b>'+t+'</b></a>').join('')+'</nav><div class="side-bottom"><div class="part-tag">BIOLOGY · 1 / 2 / 9</div><p id="save-state"><span class="saved-dot"></span>Progress saved on this browser</p><span>Small steps. Stronger understanding.</span></div></aside><main class="main"><header class="topbar"><div><button class="menu-btn" aria-label="Toggle navigation" data-action="menu">☰</button> Biology <span class="muted"> / </span><strong>'+titles[route]+'</strong></div><div class="top-right"><span class="small">Your next question is a fresh start.</span><span class="avatar" aria-label="Student profile">L</span></div></header><div class="content">'+body+'</div></main></div>'}
function header(label,title,desc,action=''){return '<div class="title-row"><div><div class="eyebrow">'+label+'</div><h1 class="page-title">'+title+'</h1><p class="muted small">'+desc+'</p></div>'+action+'</div>'}
function empty(title,desc=''){return '<div class="empty"><div class="empty-icon">◇</div><strong>'+title+'</strong><p>'+desc+'</p></div>'}
function partCards(){return '<div class="part-grid">'+PARTS.map(p=>{const qs=bank.filter(q=>q.part===p&&gradable(q)),done=qs.filter(q=>state.understood[q.id]).length,pct=qs.length?Math.round(100*done/qs.length):0;return '<article class="card"><span class="part-tag p'+p+'">PART '+p+'</span><h3>'+partNames[p]+'</h3><p>Zama + Abdulkarim · '+qs.length+' scored learning questions</p><div class="progress" role="progressbar" aria-valuenow="'+pct+'" aria-valuemin="0" aria-valuemax="100" aria-label="Part '+p+' progress"><span style="width:'+pct+'%"></span></div><div class="small muted">'+done+' / '+qs.length+' understood <span style="float:right">'+pct+'%</span></div><div class="card-footer">'+button(done?'Continue →':'Start learning →','part','ghost','data-part="'+p+'"')+'<span class="small muted">'+bank.filter(q=>q.part===p).length+' in bank</span></div></article>'}).join('')+'</div>'}
function dashboard(){const s=stats(bank,state),qs=bank.filter(gradable);shell(header('LET’S KEEP GROWING','A little progress, every day.','Learn the question. Understand the idea. Make it stick.','<a class="btn ghost" href="Learnova-Biology-Questions-Parts-1-2-9.pdf" download>↓ Questions PDF</a>')+'<section class="hero"><div class="hero-copy"><div class="eyebrow">YOUR NEXT SMALL STEP</div><h2>Biology makes more sense<br>one question at a time.</h2><p>Original questions, useful clues, and a clear path through Parts 1, 2, and 9.</p>'+button('Continue learning →','continue','primary')+'</div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 170 180" fill="none"><circle cx="85" cy="90" r="70" stroke="#446655" stroke-dasharray="3 8"/><path d="M45 20c100 45-20 95 80 140M125 20C25 65 145 115 45 160" stroke="#acd8bb" stroke-width="4"/>'+[35,60,85,110,135].map((y,i)=>'<path d="M'+(i%2?59:51)+' '+y+'h'+(i%2?53:68)+'" stroke="#8b9d88" stroke-width="3"/><circle cx="'+(i%2?59:51)+'" cy="'+y+'" r="5" fill="#b9aff4"/>').join('')+'</svg></div></section><div class="stat-grid">'+[[s.studied+'/'+qs.length,'Questions understood','Explicitly marked complete'],[s.accuracy+'%','Practice accuracy',s.attempts?'':'From submitted answers'],[state.tests.length,'Quick Tests taken','Every attempt stays saved'],[Object.values(state.bookmarks).filter(Boolean).length,'Saved bookmarks','Return when you’re ready']].map(([n,t,c])=>'<div class="stat"><span class="small muted">'+t+'</span><strong class="num">'+n+'</strong><span class="caption">'+(c||'From submitted answers')+'</span></div>').join('')+'</div><div class="section-head"><h2>Your learning path</h2><span class="small muted">Three parts. One connected course.</span></div>'+partCards()+'<div class="lower-grid"><section class="card"><div class="section-head" style="margin-top:0"><h2>Ready for a quick check?</h2><a class="text-link" href="#tests">View tests →</a></div>'+testSummary()+'</section><section class="card"><div class="section-head" style="margin-top:0"><h2>Keep these on your radar</h2><a class="text-link" href="#revision">Review →</a></div>'+weakSummary()+'</section></div><div class="footer-note">'+bank.length+' source occurrences · '+bank.filter(gradable).length+' ready for scored learning · Only Parts 1, 2 and 9. Source questions are preserved as images.</div>')}
function testSummary(){const pending=PARTS.flatMap(p=>readyBlocks(bank,p,state));return pending.length?pending.slice(0,3).map(b=>'<div class="list-row"><div><strong>Part '+b.part+' · Test '+(b.index+1)+'</strong><div class="small muted">'+b.ids.length+' questions you’ve completed</div></div>'+button('Start','test','primary','data-block="'+b.id+'"')+'</div>').join(''):empty('Your next test will appear here.','Mark a block of learning questions understood to unlock it.')}
function weakSummary(){const count={};for(const a of state.attempts.filter(a=>!a.correct)){const t=find(a.id)?.topic;if(t)count[t]=(count[t]||0)+1}return Object.keys(count).length?Object.entries(count).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([t,n])=>'<div class="list-row"><strong>'+esc(t)+'</strong><span class="pill warn">'+n+' missed attempts</span></div>').join(''):empty('A clean slate.','Topics needing practice will appear after your first answers.')}
function learning(){if(current){renderQuestion();return}shell(header('GUIDED LEARNING','Choose your next chapter.','Study original questions, then check your understanding.')+partCards()+ '<div class="notice">Learning and scored tests use questions with complete source images and reliably matched answers. Other eligible records remain visible in Compilation with their review status.</div>')}
function filtered(){let qs=bank;if(route==='mistakes')qs=qs.filter(q=>state.attempts.some(a=>a.id===q.id&&!a.correct));if(route==='bookmarks')qs=qs.filter(q=>state.bookmarks[q.id]);if(route==='revision')qs=qs.filter(q=>state.revision[q.id]||state.attempts.some(a=>a.id===q.id&&!a.correct));const query=filter.query.toLowerCase();return qs.filter(q=>(filter.part==='all'||q.part===+filter.part)&&(filter.source==='all'||q.source===filter.source)&&(filter.status==='all'||(filter.status==='verified'?q.status==='verified':filter.status==='needs_review'?q.status!=='verified':filter.status==='unanswered'?!state.attempts.some(a=>a.id===q.id):filter.status==='correct'?state.attempts.filter(a=>a.id===q.id).at(-1)?.correct===true:state.attempts.some(a=>a.id===q.id&&!a.correct)))&&(!query||[q.searchText,q.question,q.originalIdentifier,q.topic,q.source,...(q.keywords||[])].join(' ').toLowerCase().includes(query)))}
function compilation(){if(current){renderQuestion();return}const qs=filtered(),pages=Math.max(1,Math.ceil(qs.length/15));page=Math.min(page,pages-1);shell(header(route==='compilation'?'THE QUESTION BANK':'YOUR PERSONAL PRACTICE',titles[route],route==='compilation'?'Both sources, together. Explore only Parts 1, 2, and 9.':'Historical mistakes stay saved, even after a successful review.')+'<div class="toolbar"><input id="search" class="input" type="search" placeholder="Search a term, source, or question number…" aria-label="Search questions" value="'+esc(filter.query)+'"><select id="part-filter" aria-label="Filter by part"><option value="all">All parts</option>'+PARTS.map(p=>'<option value="'+p+'" '+(filter.part==p?'selected':'')+'>Part '+p+'</option>').join('')+'</select><select id="source-filter" aria-label="Filter by source">'+['all','Zama','Abdulkarim'].map(s=>'<option value="'+s+'" '+(filter.source===s?'selected':'')+'>'+(s==='all'?'Both sources':s)+'</option>').join('')+'</select><select id="status-filter" aria-label="Filter by status">'+[['all','All statuses'],['verified','Verified images'],['needs_review','Needs review'],['unanswered','Unanswered'],['correct','Last answer correct'],['missed','Previously missed']].map(([v,t])=>'<option value="'+v+'" '+(filter.status===v?'selected':'')+'>'+t+'</option>').join('')+'</select></div><div class="small muted" style="margin-bottom:16px">'+qs.length+' matching source occurrences</div><div class="bank-list">'+(qs.slice(page*15,(page+1)*15).map(q=>'<article class="bank-card"><div><div class="tags"><span class="part-tag p'+q.part+'">PART '+q.part+'</span><span class="pill">'+q.source+'</span><span class="pill '+(q.status==='verified'?'good':'warn')+'">'+(q.status==='verified'?'Source image verified':'Needs review')+'</span>'+(state.bookmarks[q.id]?'<span class="pill">Bookmarked</span>':'')+'</div><h3>'+esc(q.question||q.title||q.searchText.slice(0,160)||q.topic)+'</h3><div class="small muted">'+esc(meta(q))+' · '+(gradable(q)?'Answer matched':'Self-check / answer unresolved')+'</div></div>'+button('Open question →','open','','data-id="'+q.id+'"')+'</article>').join('')||empty('No questions here yet.','Try changing your filters or saving a question.'))+'</div><div class="pagination">'+button('← Previous','page-prev','',page===0?'disabled':'')+'<span class="small muted">'+(page+1)+' / '+pages+'</span>'+button('Next →','page-next','',page+1===pages?'disabled':'')+'</div>')}
function openQuestion(id,ids=null){current=id;viewIds=ids||filtered().map(q=>q.id);selected=null;feedback=null;round=1;state.position[find(id).part]=id;state.history.push({id,time:Date.now(),action:'open'});state.history=state.history.slice(-500);persist();renderQuestion();window.scrollTo(0,0)}
function sourceQuestion(q){return '<img class="question-image" src="'+q.image+'" tabindex="0" role="button" alt="Original '+esc(meta(q))+'. '+esc(q.question||q.title||q.topic)+'. Activate to enlarge." data-action="zoom"><p class="source-caption">Original source image · '+esc(meta(q))+(q.printedPage?' · Printed p. '+q.printedPage:'')+' · Select image to enlarge</p>'}
function explanations(q){if(!gradable(q))return '<div class="notice">An answer has not been reliably established for this occurrence. Use the source image for self-check. This question is excluded from scored tests. '+esc((q.uncertainty||[]).join(' '))+'</div>';return (q.sourceKeyAnswer&&q.sourceKeyAnswer!==q.correctAnswer?'<div class="notice">Source-key discrepancy: the scanned key lists '+q.sourceKeyAnswer+'. The English choices and reasoning support '+q.correctAnswer+'.</div>':'')+'<div class="teaching"><section><h3>Keywords to recognise</h3>'+list(q.keywords||[])+'</section><section><h3>What is this testing?</h3><div class="small">'+esc(q.concept)+'</div></section><section><h3>How to solve it</h3>'+list(q.solvingSteps||[],true)+'</section><section><h3>Why the answer fits</h3>'+list(q.explanation||[])+'</section>'+(q.memory?'<section><h3>Remember</h3><div class="small">'+esc(q.memory)+'</div></section>':'')+'</div>'}
function renderQuestion(){const q=find(current);if(!q){current=null;render();return}const idx=viewIds.indexOf(q.id),isLearning=route==='learn',canGrade=gradable(q),revealed=feedback?.reveal,done=!!state.understood[q.id];shell(header(isLearning?'LEARN · PART '+q.part:'PRACTICE · PART '+q.part,partNames[q.part],(idx+1)+' of '+viewIds.length+' in this sequence',button('← Back','back','ghost'))+'<div class="study-layout"><article class="question-card"><div class="question-meta"><div><span class="part-tag p'+q.part+'">PART '+q.part+'</span> <span class="small">'+esc(meta(q))+'</span></div><div class="tags">'+button(state.bookmarks[q.id]?'◆ Saved':'◇ Bookmark','bookmark',state.bookmarks[q.id]?'active':'')+button(state.revision[q.id]?'✓ Revision':'↺ Revise','revise',state.revision[q.id]?'active':'')+'</div></div><div class="question-body">'+sourceQuestion(q)+(q.status!=='verified'?'<div class="notice">Needs review: '+esc((q.uncertainty||[]).join(' '))+'</div>':'')+(canGrade?'<div class="choice-grid" role="group" aria-label="Answer choices">'+q.choices.map(c=>'<button class="choice '+(selected===c.id?'selected ':'')+(revealed&&c.id===q.correctAnswer?'right ':'')+(revealed&&selected===c.id&&selected!==q.correctAnswer?'wrong':'')+'" data-action="choose" data-choice="'+c.id+'" '+(revealed?'disabled':'')+'><b>'+c.id+'</b><span>'+esc(c.text||'Option '+c.id+' in the original question above')+'</span></button>').join('')+'</div>':'')+(feedback?'<div class="feedback '+(feedback.correct?'':feedback.reveal?'wrong':'hint')+'" role="status"><strong>'+esc(feedback.title)+'</strong><div>'+esc(feedback.text||'')+'</div></div>':'')+(canGrade&&!revealed?button(round===2?'Submit second attempt':'Submit answer','submit','primary',selected?'':'disabled'):'')+(revealed?explanations(q):!canGrade?explanations(q):'')+(revealed&&isLearning?'<div class="actions">'+button(done?'✓ Understood':'Mark as understood','understood','primary')+'<span class="small muted">Complete this step when the reasoning makes sense.</span></div>':'')+(!canGrade?'<div class="actions">'+button('Mark reviewed (self-check)','self-review','ghost')+'</div>':'')+'<div class="actions">'+button('← Previous','prev','',idx<=0?'disabled':'')+button('Next question →','next','',idx>=viewIds.length-1?'disabled':'')+'</div></div></article><aside class="card sidebar-card"><h3>Your question sequence</h3><div class="small muted">'+(isLearning?'Complete an explanation, then mark it understood.':'Answers are recorded only after submission.')+'</div><div class="q-dots">'+viewIds.slice(Math.max(0,Math.floor(idx/30)*30),Math.floor(idx/30)*30+30).map(id=>'<button class="q-dot '+(state.understood[id]?'done ':'')+(current===id?'current':'')+'" data-action="jump" data-id="'+id+'" aria-label="Question '+(viewIds.indexOf(id)+1)+'">'+(viewIds.indexOf(id)+1)+'</button>').join('')+'</div><div class="small muted">Only Parts 1, 2 and 9.<br>Original source records remain separate.</div></aside></div>')}
async function submit(){const q=find(current);if(!selected||!gradable(q)||feedback?.reveal)return;const correct=selected===q.correctAnswer;state.attempts.push({id:q.id,selected,correct,time:Date.now(),mode:route,round});if(!correct)state.revision[q.id]=true;const firstHint=!correct&&round===1&&route!=='learn';feedback={correct,reveal:!firstHint,title:correct?'Correct. You’ve got it.':firstHint?'Not quite — try once more.':'Let’s work through it.',text:firstHint?q.hint:'Correct answer: '+q.correctAnswer+(q.choices.find(c=>c.id===q.correctAnswer)?.text?' · '+q.choices.find(c=>c.id===q.correctAnswer).text:' (see original choice above)')};if(firstHint){round=2;selected=null}if(correct&&state.revision[q.id]){state.revision[q.id]=false;state.history.push({id:q.id,time:Date.now(),action:'reviewed'})}await persist();renderQuestion()}
function tests(){if(test){renderTest();return}if(result){renderResult();return}const bs=PARTS.flatMap(p=>blocks(bank,p));shell(header('RETRIEVE · REFLECT · REMEMBER','Quick Tests','A short check after every completed block of ten. A smaller final block counts too.')+'<div class="bank-list">'+bs.map(b=>{const ready=b.ids.every(id=>state.understood[id]),attempts=state.tests.filter(t=>t.blockId===b.id);return '<div class="bank-card"><div><span class="part-tag p'+b.part+'">PART '+b.part+'</span><h3>Quick Test '+(b.index+1)+' · '+b.ids.length+' questions</h3><div class="small muted">'+(ready?'Ready to practise':b.ids.filter(id=>state.understood[id]).length+'/'+b.ids.length+' understood to unlock')+(attempts.length?' · First: '+attempts[0].correct+'/'+attempts[0].total+' · Latest: '+attempts.at(-1).correct+'/'+attempts.at(-1).total+' · '+attempts.length+' attempts':'')+'</div></div>'+button(attempts.length?'Retry test':'Start test','test','primary','data-block="'+b.id+'" '+(!ready?'disabled':''))+'</div>'}).join('')+'</div>')}
function startTest(id){const b=PARTS.flatMap(p=>blocks(bank,p)).find(b=>b.id===id);if(!b||!b.ids.every(id=>state.understood[id]))return;route='tests';current=null;result=null;test={...b,cursor:0,answers:{},selected:null};location.hash='tests';renderTest()}
function renderTest(){const q=find(test.ids[test.cursor]);shell(header('QUICK TEST · PART '+test.part,'Stay curious. Trust your reasoning.','Question '+(test.cursor+1)+' of '+test.ids.length,button('Exit test','exit-test','ghost'))+'<div class="question-card"><div class="question-body">'+sourceQuestion(q)+'<div class="choice-grid">'+q.choices.map(c=>'<button class="choice '+(test.selected===c.id?'selected':'')+'" data-action="test-choose" data-choice="'+c.id+'"><b>'+c.id+'</b><span>'+esc(c.text||'Option '+c.id+' in the original question above')+'</span></button>').join('')+'</div>'+button(test.cursor+1===test.ids.length?'Submit and see results':'Submit and continue →','test-submit','primary',test.selected?'':'disabled')+'<p class="small muted">Answers and explanations appear after the test.</p></div></div>')}
async function testSubmit(){if(!test?.selected)return;const q=find(test.ids[test.cursor]);test.answers[q.id]=test.selected;if(test.cursor+1<test.ids.length){test.cursor++;test.selected=null;renderTest();window.scrollTo(0,0);return}const scored=score(test.ids,test.answers,bank);result={blockId:test.id,part:test.part,ids:[...test.ids],answers:{...test.answers},time:Date.now(),...scored};state.tests.push({...result});for(const id of test.ids){const q=find(id),correct=result.answers[id]===q.correctAnswer;state.attempts.push({id,selected:result.answers[id],correct,time:result.time,mode:'test',round:1});if(!correct)state.revision[id]=true}test=null;await persist();renderResult()}
function renderResult(){const missed=result.ids.filter(id=>result.answers[id]!==find(id).correctAnswer);shell(header('QUICK TEST COMPLETE','A useful check-in.','Every attempt is saved separately. Keep the learning going.')+'<div class="card test-result"><div class="score-ring"><strong>'+result.correct+'/'+result.total+'</strong><span class="small muted">correct answers</span></div>'+result.ids.map(id=>{const q=find(id),correct=result.answers[id]===q.correctAnswer;return '<div class="list-row"><div><span class="pill '+(correct?'good':'warn')+'">'+(correct?'Correct':'Review')+'</span><h3>'+esc(meta(q))+'</h3><div class="small">Your answer: '+result.answers[id]+' · Correct: '+q.correctAnswer+'</div><div class="small muted">'+esc(q.explanation?.[0]||'')+'</div><div class="small muted">Clues: '+esc((q.keywords||[]).join(' · '))+'</div></div>'+button('Review','result-review','ghost','data-id="'+id+'"')+'</div>'}).join('')+'<div class="actions">'+button('Review mistakes ('+missed.length+')','review-test','',''+(!missed.length?'disabled':''))+button('Retry after review','retry-test','ghost')+button('Continue learning →','continue','primary')+'</div></div>')}
function statistics(){const s=stats(bank,state);shell(header('YOUR LEARNING, IN VIEW','Small efforts add up.','All statistics come from your saved actions.')+'<div class="stat-grid">'+[[s.studied,'Understood'],[s.attempted,'Questions attempted'],[s.wrong,'Incorrect attempts'],[s.accuracy+'%','Practice accuracy']].map(([n,t])=>'<div class="stat"><span class="small muted">'+t+'</span><strong class="num">'+n+'</strong></div>').join('')+'</div>'+partCards()+'<div class="lower-grid"><div class="card"><h3>Weak topics</h3>'+weakSummary()+'</div><div class="card"><h3>Quick Test history</h3>'+(state.tests.length?state.tests.slice().reverse().slice(0,15).map(t=>'<div class="list-row"><span class="small">'+t.blockId+' · '+new Date(t.time).toLocaleDateString()+'</span><strong>'+t.correct+'/'+t.total+'</strong></div>').join(''):empty('No test attempts yet.'))+'</div></div>')}
function settings(){shell(header('MAKE THIS SPACE YOURS','Your progress, under your control.','Progress stays in this browser. Export a backup to move it to another browser.')+'<section class="card"><div class="setting-row"><div><strong>Export progress</strong><p class="small muted">Includes answers, test history, bookmarks, and your position.</p></div>'+button('↓ Export backup','export','primary')+'</div><div class="setting-row"><div><strong>Import a backup</strong><p class="small muted">Validated before replacing your current progress.</p></div><label class="btn" for="import-progress">↑ Import backup</label><input class="file-input" id="import-progress" type="file" accept=".json,application/json"></div><div class="setting-row"><div><strong>Questions PDF</strong><p class="small muted">Only the eligible, usable questions from Parts 1, 2, and 9.</p></div><a class="btn" href="Learnova-Biology-Questions-Parts-1-2-9.pdf" download>↓ Download PDF</a></div><div class="setting-row"><div><strong>Reset progress</strong><p class="small muted">Deletes your saved study history in this browser.</p></div>'+button('Reset progress','reset','danger')+'</div><p class="small muted">Question content and your progress are stored separately. Closing a page does not erase your saved actions.</p></section>')}
function render(){if(route==='dashboard')dashboard();else if(route==='learn')learning();else if(['compilation','mistakes','revision','bookmarks'].includes(route))compilation();else if(route==='tests')tests();else if(route==='statistics')statistics();else settings()}
document.addEventListener('click',e=>{const link=e.target.closest('.nav a');if(!link)return;e.preventDefault();if(test&&!confirm('Leave the unfinished test?'))return;test=null;result=null;current=null;route=link.getAttribute('href').slice(1);location.hash=route;render();window.scrollTo(0,0)});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;try{if(a==='menu')$('.sidebar').classList.toggle('open');if(a==='zoom')el.classList.toggle('zoomed');if(a==='part'){route='learn';current=null;const ids=bank.filter(q=>q.part===+el.dataset.part&&gradable(q)).map(q=>q.id);location.hash='learn';if(ids.length)openQuestion(ids.includes(state.position[el.dataset.part])?state.position[el.dataset.part]:ids[0],ids);else learning()}
if(a==='continue'){test=null;result=null;route='learn';const last=state.history.slice().reverse().find(h=>find(h.id)&&gradable(find(h.id)))?.id;const same=last?bank.filter(q=>q.part===find(last).part&&gradable(q)):[];const id=(last&&!state.understood[last]?last:same.find(q=>!state.understood[q.id])?.id)||bank.find(q=>gradable(q)&&!state.understood[q.id])?.id||last||bank.find(gradable)?.id;location.hash='learn';if(id)openQuestion(id,bank.filter(q=>q.part===find(id).part&&gradable(q)).map(q=>q.id));else learning()}
if(a==='open'||a==='jump')openQuestion(el.dataset.id,a==='jump'?viewIds:null);
if(a==='back'){current=null;render()}if(a==='choose'){selected=el.dataset.choice;renderQuestion()}if(a==='submit')await submit();
if(a==='bookmark'||a==='revise'){const key=a==='bookmark'?'bookmarks':'revision';state[key][current]=!state[key][current];await persist();renderQuestion()}
if(a==='understood'){state.understood[current]=true;await persist();const pending=readyBlocks(bank,find(current).part,state);if(pending.length){startTest(pending[0].id);toast('Block completed. Your Quick Test is ready.')}else{toast('Marked as understood.');renderQuestion()}}
if(a==='self-review'){state.history.push({id:current,time:Date.now(),action:'self-review'});state.revision[current]=false;await persist();toast('Review saved. This is not a scored answer.')}
if(a==='prev'||a==='next'){const i=viewIds.indexOf(current)+(a==='next'?1:-1);if(viewIds[i])openQuestion(viewIds[i],viewIds)}
if(a==='page-prev'||a==='page-next'){page+=a==='page-next'?1:-1;compilation();window.scrollTo(0,0)}
if(a==='test')startTest(el.dataset.block);if(a==='test-choose'){test.selected=el.dataset.choice;renderTest()}if(a==='test-submit')await testSubmit();
if(a==='exit-test'&&confirm('Leave this unfinished test? Submitted learning progress is already saved.')){test=null;tests()}
if(a==='result-review'){route='revision';location.hash='revision';openQuestion(el.dataset.id,result.ids)}if(a==='review-test'){const ids=result.ids.filter(id=>result.answers[id]!==find(id).correctAnswer);route='revision';location.hash='revision';openQuestion(ids[0],ids)}
if(a==='retry-test')startTest(result.blockId);
if(a==='export'){const dialog=document.createElement('dialog');dialog.id='backup-dialog';dialog.innerHTML='<h2>Keep a progress backup</h2><p class="muted small">Save the file, or copy the backup text if downloads are unavailable.</p><textarea id="backup-text" readonly aria-label="Progress backup JSON"></textarea><div class="actions">'+button('Save JSON file','download-backup','primary')+button('Copy backup','copy-backup')+button('Close','close-backup','ghost')+'</div>';document.body.appendChild(dialog);dialog.querySelector('textarea').value=JSON.stringify(state,null,2);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal()}
if(a==='download-backup'){const blob=new Blob([$('#backup-text').value],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='learnova-progress-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
if(a==='copy-backup'){try{await navigator.clipboard.writeText($('#backup-text').value);toast('Backup copied.')}catch{$('#backup-text').select();toast('Backup selected. Copy it and save it in a text file.')}}
if(a==='close-backup')$('#backup-dialog').close();
if(a==='reset'&&confirm('Reset all saved learning progress, answers, tests, and bookmarks? Export a backup first if you want to keep them.')){state=fresh();await persist();settings();toast('Progress reset.')}
}catch(err){toast(err.message||'Something went wrong. Please try again.')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;filter.query=e.target.value;page=0;compilation();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
document.addEventListener('change',async e=>{for(const [id,key] of [['part-filter','part'],['source-filter','source'],['status-filter','status']])if(e.target.id===id){filter[key]=e.target.value;page=0;compilation()}if(e.target.id==='import-progress'&&e.target.files[0]){try{const next=await importFile(e.target.files[0],bank);if(confirm('Replace current progress with this validated backup?')){state=next;await persist();settings();toast('Progress imported.')}}catch(err){toast('Import failed: '+err.message)}}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'dashboard';if(!titles[next])return;if(next!==route){if(test&&!confirm('Leave the unfinished test?')){location.hash='tests';return}test=null;current=null;result=null;route=next;render();window.scrollTo(0,0)}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.question-image')){e.preventDefault();e.target.classList.toggle('zoomed')}if(e.key==='Escape')document.querySelector('.question-image.zoomed')?.classList.remove('zoomed')});
async function boot(){try{bank=EMBEDDED_QUESTIONS;if(!bank.length||bank.some(q=>!PARTS.includes(q.part)))throw Error('Question scope check failed.');state=validateProgress(await openStore(),bank);route=titles[location.hash.slice(1)]?location.hash.slice(1):'dashboard';render()}catch(err){$('#app').innerHTML='<div class="error"><h1>We couldn’t open your study space.</h1><p>'+esc(err.message)+'</p><p>This copy is designed to run directly from index.html. Try refreshing the page.</p><button class="btn" onclick="location.reload()">Try again</button></div>'}}
boot();
